import { buildNpbCatalog } from "../../src/application/npb-product-payload";
import { npbTeams } from "../../src/data/npb-nf3";
import { historicalBattingKeys, historicalPitchingKeys, npbHistoricalDatasetSchema, npbHistoricalManifestSchema } from "../../src/domain/npb-historical";

export const cohortId=(n:number)=>`00000000-0000-4000-8000-${String(n).padStart(12,"0")}`;
export function cohortFixture(count=7){
  const catalog=buildNpbCatalog({schemaVersion:2,league:"NPB",effectiveDate:"2026-10-12",generatedAt:"2026-10-13T00:00:00Z",teams:npbTeams.map(t=>({id:t.id,name:t.name,shortName:t.short})),players:Array.from({length:count},(_,i)=>({playerId:cohortId(i),displayName:i<2?"同姓同名":`架空選手${i}`,teamId:"npb:team:tigers",position:null,playerType:null,birthDate:i===2?null:i===3?"2000-01-01":"1999-12-31",birthPlace:null,nationality:null,bats:null,throws:null,battingAvailable:true,pitchingAvailable:true,recentAvailable:true}))},{observedAt:"2026-10-13T00:00:00Z",effectiveDate:"2026-10-12",players:[]});
  catalog.players.forEach((p,i)=>{p.profile.draftYear=i===4?null:i<2?2017:2018;p.profile.credits=[{name:"架空プロフィール出典",url:"https://example.com/identity/"+i,licenseUrl:"https://creativecommons.org/publicdomain/zero/1.0/",fields:["birthDate","draftYear"],modified:true}];});
  const batting=(i:number,ab=100,h=20)=>({playerId:cohortId(i),season:2025,teamId:"npb:team:tigers",role:"batting",metrics:{...Object.fromEntries(historicalBattingKeys.map(k=>[k,null])),PA:ab+2,AB:ab,H:h,TB:h,BB:2,HBP:0,SF:0,SH:0,HR:0}});
  const data=npbHistoricalDatasetSchema.parse({schemaVersion:1,league:"NPB",temporalScope:"historical",competition:"regular",granularity:"season_aggregate",license:"CC-BY-SA-4.0",observedAt:"2026-10-13T00:00:00Z",inputSha256:"a".repeat(64),transformation:"Synthetic fixture only",coverage:"partial",players:catalog.players.map((p,i)=>({playerId:p.playerId,name:p.displayName,wikidataId:`Q${i+100}`,npbId:String(i+10000000),article:`架空記事${i}`,revision:i+100,revisionAt:"2026-01-01T00:00:00Z",contentSha256:"b".repeat(64)})),rows:[...catalog.players.flatMap((_,i)=>i===6?[]:[batting(i)]),{...batting(0,10,5),teamId:"npb:team:hawks"},{playerId:cohortId(6),season:2025,teamId:"npb:team:tigers",role:"pitching",metrics:{...Object.fromEntries(historicalPitchingKeys.map(k=>[k,null])),outsRecorded:0,H:1,BB:1,SO:0}}]});
  const manifest=npbHistoricalManifestSchema.parse({schemaVersion:1,league:"NPB",competition:"regular",temporalScope:"historical",coverage:"partial",license:data.license,inputSha256:data.inputSha256,observedAt:data.observedAt,seasons:[{season:2025,rows:data.rows.length,players:data.players.length,sha256:"b".repeat(64),bytes:1000}],players:data.players.map(p=>({playerId:p.playerId,name:p.name,seasons:[2025]}))});
  return {catalog,data,manifest};
}
